with(sys_mouse)
{
    if vab_unit=1
    {
        if instance_number(vab_unit_id[0])
        {
            draw_sprite_ext(global.unit_id_spr[vab_unit_id[0].unit_id, 0], 0, other.x+200, other.y+280, 30/sprite_get_width(global.unit_id_spr[vab_unit_id[0].unit_id, 0]), 30/sprite_get_height(global.unit_id_spr[vab_unit_id[0].unit_id, 0]), 0, -1, 1)
            if vab_unit_id[0].unit_cre_number=0 or global.player_control!=vab_unit_id[0].player
            {
                draw_set_color(c_white)
                draw_sprite(spr_name_ico, -1, other.x+230, other.y+260)
                sex_draw_text(other.x+245, other.y+255, vab_unit_id[0].name)
                //이름
                draw_sprite(spr_hp_ico, -1, other.x+230, other.y+280)
                draw_text(other.x+245, other.y+275, string(vab_unit_id[0].hp)+"/"+string(vab_unit_id[0].max_hp))
                //체력
                draw_sprite(spr_att_ico, -1, other.x+330, other.y+260)
                draw_text(other.x+345, other.y+255, vab_unit_id[0].attack_power)
                //공격력
                draw_sprite(spr_mov_ico, -1, other.x+330, other.y+280)
                draw_text(other.x+345, other.y+275, vab_unit_id[0].move_speed)
                //이속
                draw_sprite(spr_nf_ico, -1, other.x+430, other.y+260)
                sk_udraw_color(vab_unit_id[0].player)
                draw_text(other.x+445, other.y+253, "player : "+string(vab_unit_id[0].player))
                draw_set_color(c_black)
                //국가
            }
        }
    }
}

with(sys_mouse)
{
    if vab_unit>1
    {
        for(i=0; i!=vab_unit; i+=1)
        {
            if instance_number(vab_unit_id[i])
            {
                if !sk_mouse_check(other.x+195+(i*35), other.y+255, other.x+225+(i*35), other.y+285){draw_sprite_ext(global.unit_id_spr[vab_unit_id[i].unit_id, 0], 0, other.x+210+(i*35), other.y+270, 30/sprite_get_width(global.unit_id_spr[vab_unit_id[i].unit_id, 0]), 30/sprite_get_height(global.unit_id_spr[vab_unit_id[i].unit_id, 0]), 0, -1, 0.5)}
                else{draw_sprite_ext(global.unit_id_spr[vab_unit_id[i].unit_id, 0], 0, other.x+210+(i*35), other.y+270, 30/sprite_get_width(global.unit_id_spr[vab_unit_id[i].unit_id, 0]), 30/sprite_get_height(global.unit_id_spr[vab_unit_id[i].unit_id, 0]), 0, -1, 1)}
                draw_rectangle(other.x+195+(i*35), other.y+255, other.x+225+(i*35), other.y+285, 1)
                draw_set_color(c_red)
                gauge_bar(vab_unit_id[i].hp, vab_unit_id[i].max_hp, other.x+195+(i*35), other.y+287, other.x+225+(i*35), other.y+290, 0)
                draw_set_color(c_black)
                gauge_bar_back(other.x+195+(i*35), other.y+287, other.x+225+(i*35), other.y+290, 0)
            }
        }
    }
}

