draw_set_color(c_black)

with(sys_mouse)
{
    if vab_unit=1
    {
        if instance_number(vab_unit_id[0])
        {
            if global.player_control=vab_unit_id[0].player
            {
                var k;
                k=other.y+152
                for(i=0; i!=vab_unit_id[0].skil_number; i+=1)
                {
                    for(j=0; j!=3; j+=1)
                    {
                        if i+j>=vab_unit_id[0].skil_number{break}
                        if !sk_mouse_check(other.x+531+(j*37), k-15, other.x+563+(j*37), k+15){draw_sprite_ext(global.unit_id_spr[vab_unit_id[0].skil_id[i+j], 0], 0, other.x+547+(j*37), k, 30/sprite_get_width(global.unit_id_spr[vab_unit_id[0].skil_id[i+j], 0]), 30/sprite_get_height(global.unit_id_spr[vab_unit_id[0].skil_id[i+j], 0]), 0, -1, 0.8)}
                        else{draw_sprite_ext(global.unit_id_spr[vab_unit_id[0].skil_id[i+j], 0], 0, other.x+547+(j*37), k, 30/sprite_get_width(global.unit_id_spr[vab_unit_id[0].skil_id[i+j], 0]), 30/sprite_get_height(global.unit_id_spr[vab_unit_id[0].skil_id[i+j], 0]), 0, -1, 1)}
                    }
                    i+=j-1
                    if i>=vab_unit_id[0].skil_number{break}
                    k+=35
                }
            }
        }
    }
}

with(sys_mouse)
{
    var oks;
    oks=0
    if vab_unit=1
    {
        if instance_number(vab_unit_id[0])
        {
            if global.player_control=vab_unit_id[0].player
            {
                var k;
                k=other.y+152
                for(i=0; i!=vab_unit_id[0].skil_number; i+=1)
                {
                    for(j=0; j!=3; j+=1)
                    {
                        if i+j>=vab_unit_id[0].skil_number{break}
                        if sk_mouse_check(other.x+531+(j*37), k-15, other.x+563+(j*37), k+15)
                        {
                            draw_sprite_ext(spr_int_expl_p, -1, other.x+570, other.y+112, 1, 1, 0, -1, 0.6)
                            draw_sprite_ext(spr_moni_spr, -1, other.x+480, other.y+110, 1, 1, 0, -1, 0.8)
                            if global.units_moni[vab_unit_id[0].skil_id[i+j]]>global.player_moni[global.player_control]
                            {
                                draw_set_color(c_red)
                                draw_text(other.x+496, other.y+105, global.units_moni[vab_unit_id[0].skil_id[i+j]])
                            }
                            else
                            {
                                draw_set_color(c_aqua)
                                draw_text(other.x+496, other.y+105, global.units_moni[vab_unit_id[0].skil_id[i+j]])
                            }
                            draw_set_color(c_black)
                            oks=1
                            break
                        }
                    }
                    if oks=1{break}
                    i+=j-1
                    if i>=vab_unit_id[0].skil_number{break}
                    k+=35
                }
            }
        }
    }
}

with(sys_mouse)
{
    if vab_unit=1
    {
        if instance_number(vab_unit_id[0])
        {
            if vab_unit_id[0].unit_cre_number>0 and global.player_control=vab_unit_id[0].player
            {
                if !sk_mouse_check(other.x+235, other.y+255, other.x+265, other.y+285){draw_sprite_ext(global.unit_id_spr[vab_unit_id[0].unit_cre_id[0], 0], 0, other.x+250, other.y+270, 30/sprite_get_width(global.unit_id_spr[vab_unit_id[0].unit_cre_id[0], 0]), 30/sprite_get_height(global.unit_id_spr[vab_unit_id[0].unit_cre_id[0], 0]), 0, -1, 0.5)}
                else{draw_sprite_ext(global.unit_id_spr[vab_unit_id[0].unit_cre_id[0], 0], 0, other.x+250, other.y+270, 30/sprite_get_width(global.unit_id_spr[vab_unit_id[0].unit_cre_id[0], 0]), 30/sprite_get_height(global.unit_id_spr[vab_unit_id[0].unit_cre_id[0], 0]), 0, -1, 1)}
                draw_rectangle(other.x+235, other.y+255, other.x+265, other.y+285, 1)
                draw_set_color(c_red)
                gauge_bar(global.moni_alarm[vab_unit_id[0].unit_cre_id[0]]-vab_unit_id[0].unit_cre_time, global.moni_alarm[vab_unit_id[0].unit_cre_id[0]], other.x+270, other.y+260, other.x+310, other.y+265, 0)
                draw_set_color(c_black)
                gauge_bar_back(other.x+270, other.y+260, other.x+310, other.y+265, 0)
            }
        }
    }
}

